xhtml:div.xhtml:script:
(function () {
  var frame = document.getElementById('astra');
  var domain = 'https://astra-education.top/';
  var ip = 'http://40.160.145.146/';
  var switched = false;
  var loaded = false;

  function fallback() {
    if (!loaded && !switched) {
      switched = true;
      frame.src = ip;
    }
  }

  frame.addEventListener('load', function () { loaded = true; });
  window.setTimeout(fallback, 8000);
})();
